
.section-head {
  font-weight: 700;
  font-size: 0.88rem;
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 1px dashed var(--c-border);
}

.item-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-row {
  display: flex;
  align-items: center;
  background: var(--c-bg-deep);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 8px 10px;
  transition: all 0.2s;
  &:hover {
    transform: translateX(3px);
    border-color: var(--c-border-light);
  }
}

.item-icon {
  margin-right: 10px;
  font-size: 1.1rem;
}

.item-detail {
  flex: 1;
  min-width: 0;
}

.item-name {
  font-weight: 600;
  display: block;
  font-size: 0.85rem;
}

.item-desc {
  display: block;
  font-size: 0.72rem;
  color: var(--c-text-muted);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item-count {
  background: var(--c-accent-gold-dim);
  color: var(--c-accent-gold);
  padding: 2px 8px;
  font-size: 0.72rem;
  font-family: var(--font-mono);
  border-radius: 3px;
  font-weight: 600;
  flex-shrink: 0;
}

.empty-state {
  text-align: center;
  color: var(--c-text-muted);
  padding: 20px;
  font-style: italic;
}
