
.section-head {
  font-weight: 700;
  font-size: 0.88rem;
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 1px dashed var(--c-border);
}

.asset-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.asset-card {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--c-bg-deep);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 8px 10px;
  transition: all 0.2s;
  &:hover {
    border-color: var(--c-border-light);
  }
}

.asset-icon {
  font-size: 1.2rem;
  flex-shrink: 0;
}

.asset-info {
  flex: 1;
  min-width: 0;
}

.asset-name {
  font-weight: 600;
  font-size: 0.85rem;
}

.asset-meta {
  display: flex;
  gap: 6px;
  margin-top: 3px;
}

.asset-type,
.asset-status {
  font-size: 0.68rem;
  padding: 1px 6px;
  border-radius: 3px;
}

.asset-type {
  background: var(--c-accent-blue-dim);
  color: var(--c-accent-blue);
}

.status-good {
  background: var(--c-accent-green-dim);
  color: var(--c-accent-green);
}
.status-bad {
  background: var(--c-accent-red-dim);
  color: var(--c-accent-red);
}
.status-neutral {
  background: rgba(139, 148, 158, 0.15);
  color: var(--c-text-secondary);
}

.asset-value {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--c-accent-gold);
  font-weight: 600;
  white-space: nowrap;
}

.empty-state {
  text-align: center;
  color: var(--c-text-muted);
  padding: 20px;
  font-style: italic;
}
